{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Pricing — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Clear frameworks, habit-focused offers — plans that pair guidance with daily practices.">
  <style>
    :root{--bg:#fbfbfa;--muted:#6b6b6b;--accent:#6aa84f;--ink:#1b1b1b;--card:#ffffff;--glass:rgba(255,255,255,0.6)}
    html,body{height:100%;margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;color:var(--ink);background:linear-gradient(180deg,#fbfff6 0%,#fbfbfa 50%);}
    header{display:flex;align-items:center;justify-content:space-between;padding:22px 28px;max-width:1100px;margin:0 auto}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#5aa3c8);display:grid;place-items:center;color:white;font-weight:700}
    nav a{margin-left:18px;text-decoration:none;color:var(--muted);font-weight:600}
    .wrap{max-width:1100px;margin:28px auto;padding:0 20px}
    .hero{display:grid;grid-template-columns:1fr 360px;gap:28px;align-items:start}
    .hero .intro{background:var(--card);padding:28px;border-radius:12px;box-shadow:0 6px 22px rgba(30,30,30,0.06)}
    h1{margin:0 0 8px 0;font-size:28px;line-height:1.05}
    p.lead{margin:0;color:var(--muted)}
    .right{padding:22px;background:linear-gradient(180deg,rgba(106,168,79,0.06),rgba(90,163,200,0.03));border-radius:12px}
    .tier-grid{display:flex;gap:16px;margin-top:22px}
    .tier{flex:1;background:var(--card);padding:18px;border-radius:10px;border:1px solid rgba(30,30,30,0.04)}
    .tier h3{margin:0 0 6px 0}
    .price{font-size:22px;font-weight:700;margin:6px 0}
    .list{color:var(--muted);font-size:14px}
    .cta{display:inline-block;margin-top:12px;padding:10px 14px;background:var(--accent);color:white;border-radius:8px;text-decoration:none}
    .micro{font-size:13px;color:var(--muted);margin-top:10px}
    footer{max-width:1100px;margin:38px auto;padding:18px 20px;color:var(--muted);font-size:13px}
    /* Habit builder */
    .habit-builder{margin-top:22px;background:linear-gradient(180deg,#fff,#fbfff8);padding:16px;border-radius:10px;border:1px solid rgba(30,30,30,0.04)}
    .hb-controls{display:flex;gap:8px;flex-wrap:wrap}
    input[type=text]{padding:8px 10px;border-radius:8px;border:1px solid rgba(30,30,30,0.06);min-width:180px}
    button{padding:9px 12px;border-radius:8px;border:0;background:#333;color:#fff;cursor:pointer}
    .print-area{margin-top:12px;background:var(--glass);padding:12px;border-radius:8px}
    .checkgrid{display:grid;grid-template-columns:repeat(8,1fr);gap:6px}
    .checkgrid .day{padding:8px;background:white;border-radius:8px;border:1px solid rgba(30,30,30,0.04);font-size:13px;text-align:center}
    /* Modal */
    .modal{position:fixed;inset:0;display:none;align-items:center;justify-content:center;background:rgba(8,8,8,0.36);z-index:60}
    .modal.open{display:flex}
    .modal-card{width:520px;max-width:92%;background:var(--card);padding:18px;border-radius:12px}
    .modal h4{margin:0 0 8px 0}
    .exercise-visual{height:120px;display:grid;place-items:center}
    .progress-ring{width:96px;height:96px}
    .controls{display:flex;gap:8px;justify-content:flex-end;margin-top:12px}
    .tiny{font-size:12px;color:var(--muted)}
    @media(max-width:880px){.hero{grid-template-columns:1fr}.right{order:2}.intro{order:1}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">W</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html">Story</a>
      <a href="programs.html">Paths</a>
      <a href="pricing.html">Pricing</a>
      <a href="testimonials.html">Voices</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main class="wrap">
    <section class="hero">
      <div class="intro">
        <h1>Pricing shaped around steady practice</h1>
        <p class="lead">Choose a tier that gives you clear next steps, daily habits, and checklists that fit your life. Hybrid options combine one-on-one time with structured daily tasks.</p>

        <div class="tier-grid">
          <div class="tier">
            <h3>Pulse Plan</h3>
            <div class="price">$45 / session + habit kit</div>
            <div class="list">Single consult, tailored habit map, 7-day starter checklist.</div>
            <a class="cta" href="{{PRIMARY_CTA_URL}}">Reserve a session</a>
            <div class="micro">Pay per session. Ideal for a focused reset.</div>
          </div>
          <div class="tier">
            <h3>Compass Subscription</h3>
            <div class="price">$99 / month</div>
            <div class="list">Weekly check-ins, evolving habit templates, small group Q&amp;A.</div>
            <a class="cta" href="{{PRIMARY_CTA_URL}}">Start the month</a>
            <div class="micro">Ongoing guidance and practical nudges for daily life.</div>
          </div>
          <div class="tier">
            <h3>Orchard Intensive</h3>
            <div class="price">$420 / 8 weeks</div>
            <div class="list">Deep framework, weekly coaching, tailored 7-day sequences, habit review tools.</div>
            <a class="cta" href="{{PRIMARY_CTA_URL}}">Join a cohort</a>
            <div class="micro">Structured program with measurable practice milestones.</div>
          </div>
        </div>

        <div class="habit-builder" aria-labelledby="hb">
          <strong id="hb">Create a 7-day checklist</strong>
          <div style="margin-top:8px;color:var(--muted)">Name up to 3 focused habits you'd like to anchor this week.</div>
          <div style="margin-top:10px" class="hb-controls">
            <input id="habit1" type="text" placeholder="Morning habit (e.g. 3 breaths)" />
            <input id="habit2" type="text" placeholder="Movement or short practice" />
            <input id="habit3" type="text" placeholder="Evening habit or note" />
            <button id="generate">Make checklist</button>
            <button id="printBtn">Print</button>
            <button id="tryNowBtn">Try a quick practice</button>
          </div>

          <div id="printArea" class="print-area" style="display:none">
            <div style="display:flex;justify-content:space-between;align-items:center">
              <strong>7-day checklist</strong>
              <div class="tiny">Ready to tick off each day</div>
            </div>
            <div id="checkGrid" class="checkgrid" style="margin-top:10px">
              <!-- Generated days -->
            </div>
          </div>
        </div>

      </div>

      <aside class="right">
        <h3>Why this frame?</h3>
        <p class="tiny">Prices reflect a blend of coaching time and daily practice tools. Each plan is built around habits and outcomes — no medical promises, only steadier routines and frameworks you can use.</p>

        <div style="margin-top:12px">
          <strong>Need a quick exercise?</strong>
          <div style="margin-top:8px;color:var(--muted)">Open a guided micro-practice that fits into a coffee break.</div>
          <div style="margin-top:10px"><button id="tryNowBtn2">Open practice</button></div>
        </div>
      </aside>
    </section>

  </main>

  <footer>
    <div>Contact: <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • {{CITY}}, {{STATE}}</div>
  </footer>

  <!-- Modal for guided practice -->
  <div id="modal" class="modal" role="dialog" aria-modal="true">
    <div class="modal-card">
      <h4 id="modalTitle">Micro Practice</h4>
      <div id="modalBody">
        <div style="display:flex;gap:12px;align-items:center;justify-content:space-between">
          <div>
            <label for="exerciseSelect">Choose</label>
            <select id="exerciseSelect" style="margin-left:8px;padding:6px;border-radius:8px">
              <option value="breath">Breathing (2 min)</option>
              <option value="journal">Journaling prompt (5 min)</option>
              <option value="intention">Set an intention (3 min)</option>
            </select>
          </div>
          <div class="tiny">A small guided pause</div>
        </div>
        <div class="exercise-visual" style="margin-top:12px">
          <svg class="progress-ring" viewBox="0 0 120 120" aria-hidden="true">
            <circle cx="60" cy="60" r="44" stroke="#eee" stroke-width="12" fill="none"></circle>
            <circle id="ring" cx="60" cy="60" r="44" stroke="var(--accent)" stroke-width="12" fill="none" stroke-linecap="round" stroke-dasharray="276.46" stroke-dashoffset="276.46"></circle>
            <text id="timeLabel" x="60" y="66" text-anchor="middle" font-size="16" fill="var(--muted)">Start</text>
          </svg>
        </div>
        <div style="margin-top:10px;color:var(--muted)" id="exerciseText">Select an exercise and press Start.</div>
        <div class="controls">
          <button id="closeModal">Close</button>
          <button id="startBtn">Start</button>
        </div>
      </div>
    </div>
  </div>

  <script>
    // Habit builder logic
    function $(id){return document.getElementById(id)}
    const generate = $('generate');
    const printArea = $('printArea');
    const checkGrid = $('checkGrid');
    const printBtn = $('printBtn');
    const tryNowBtn = $('tryNowBtn');
    const tryNowBtn2 = $('tryNowBtn2');

    function makeGrid(){
      const h1 = $('habit1').value.trim();
      const h2 = $('habit2').value.trim();
      const h3 = $('habit3').value.trim();
      const habits = [h1,h2,h3].filter(Boolean);
      checkGrid.innerHTML = '';
      const labels = ['Day','Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
      // header
      labels.forEach(lbl=>{
        const el = document.createElement('div');
        el.className='day';
        el.style.fontWeight='600';
        el.textContent = lbl;
        checkGrid.appendChild(el);
      });
      // rows per habit
      if(habits.length===0){
        const el=document.createElement('div');el.className='day';el.style.gridColumn='1/-1';el.textContent='Add a habit to begin';checkGrid.appendChild(el);return;
      }
      habits.forEach(h=>{
        const title = document.createElement('div');title.className='day';title.textContent=h;title.style.fontSize='13px';title.style.fontWeight='600';checkGrid.appendChild(title);
        for(let i=0;i<7;i++){const box=document.createElement('div');box.className='day';box.innerHTML='<input type="checkbox" style="width:16px;height:16px">';box.style.display='flex';box.style.justifyContent='center';box.style.alignItems='center';checkGrid.appendChild(box);}
      });
      printArea.style.display='block';
    }
    generate.addEventListener('click',makeGrid);
    printBtn.addEventListener('click',()=>{window.print();});

    // Modal guided practice logic
    const modal = $('modal');
    const closeModal = $('closeModal');
    const startBtn = $('startBtn');
    const exerciseSelect = $('exerciseSelect');
    const exerciseText = $('exerciseText');
    const ring = $('ring');
    const timeLabel = $('timeLabel');

    function openModal(){modal.classList.add('open');}
    function close(){modal.classList.remove('open');resetRing();}
    tryNowBtn.addEventListener('click',openModal);
    tryNowBtn2.addEventListener('click',openModal);
    closeModal.addEventListener('click',close);

    let timer = null;
    function resetRing(){ring.style.transition='none';ring.style.strokeDashoffset=276.46;timeLabel.textContent='Start';exerciseText.textContent='Select an exercise and press Start.'}
    function startExercise(){
      const choice = exerciseSelect.value;
      let seconds = 120; // default 2 min
      if(choice==='breath') seconds = 120;
      if(choice==='journal') seconds = 300;
      if(choice==='intention') seconds = 180;
      const start = Date.now();
      exerciseText.textContent = {breath:'Follow slow inhales and exhales. Breathe in for 4, out for 5.',journal:'Write without judgement. Prompt: What matters most today?',intention:'Choose one clear intention for the next hour.'}[choice];
      ring.style.transition='stroke-dashoffset 1s linear';
      if(timer) clearInterval(timer);
      timer = setInterval(()=>{
        const elapsed = Math.floor((Date.now()-start)/1000);
        const remaining = Math.max(0, seconds - elapsed);
        const pct = remaining / seconds;
        ring.style.strokeDashoffset = (276.46 * pct).toFixed(2);
        timeLabel.textContent = (remaining>0)? remaining + 's' : 'Done';
        if(remaining<=0){clearInterval(timer);timer=null;timeLabel.textContent='Done';}
      },200);
    }
    startBtn.addEventListener('click',startExercise);

    // Close on outside click
    modal.addEventListener('click',e=>{if(e.target===modal)close();});

    // small accessibility: open via keyboard shortcut 'P' for practice
    document.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='p'){openModal();}});
  </script>
</body>
</html>"} 
{"path":"testimonials.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Voices — Client Stories</title>
  <meta name="description" content="Real accounts of steady habit changes, short and long arcs.">
  <style>
    :root{--bg:#fcfcfb;--ink:#101010;--muted:#606060;--accent:#8c6dfd}
    body{margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;background:var(--bg);color:var(--ink)}
    .site{max-width:960px;margin:22px auto;padding:18px}
    header{display:flex;justify-content:space-between;align-items:center}
    nav a{margin-left:14px;text-decoration:none;color:var(--muted);font-weight:600}
    .hero{padding:18px 0}
    h1{margin:0 0 6px 0}
    .grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}
    .card{background:white;padding:14px;border-radius:12px;border:1px solid rgba(16,16,16,0.04)}
    .quote{font-style:italic;color:var(--muted)}
    .meta{font-size:13px;color:var(--muted);margin-top:8px}
    .cta{margin-top:12px;display:inline-block;padding:8px 12px;background:var(--accent);color:white;border-radius:8px;text-decoration:none}
    /* small layout changes */
    @media(max-width:720px){.grid{grid-template-columns:1fr}}
    /* Pattern header */
    .pattern{height:56px;border-radius:10px;background:linear-gradient(90deg,#fff,#f7f6ff);display:flex;align-items:center;padding:10px}
    .tiny{font-size:13px;color:var(--muted)}
    /* Modal reused */
    .modal{position:fixed;inset:0;display:none;align-items:center;justify-content:center;background:rgba(8,8,8,0.36);z-index:60}
    .modal.open{display:flex}
    .modal-card{width:520px;max-width:92%;background:#fff;padding:18px;border-radius:12px}
    .controls{display:flex;gap:8px;justify-content:flex-end;margin-top:12px}
  </style>
</head>
<body>
  <div class="site">
    <header>
      <div style="display:flex;gap:12px;align-items:center">
        <div style="width:44px;height:44px;border-radius:8px;background:linear-gradient(135deg,#8c6dfd,#6fc3a6);display:grid;place-items:center;color:white;font-weight:700">W</div>
        <div>
          <div style="font-weight:700">{{BUSINESS_NAME}}</div>
          <div class="tiny">Notes on steady practice</div>
        </div>
      </div>
      <nav>
        <a href="index.html">Home</a>
        <a href="services.html">Offerings</a>
        <a href="testimonials.html">Voices</a>
        <a href="book.html">Book</a>
        <a href="contact.html">Connect</a>
      </nav>
    </header>

    <section class="hero">
      <div class="pattern">
        <strong style="margin-right:8px">Client Voices</strong>
        <div style="color:var(--muted)">Short reports on habit shifts and new daily shapes.</div>
      </div>
    </section>

    <section style="margin-top:16px">
      <div class="grid">
        <div class="card">
          <div class="quote">"I stopped waiting for perfect time. The tiny sequence fit my messy mornings."</div>
          <div class="meta">– L., 38, teacher. Joined a 6-week path focused on micro-routines.</div>
        </div>
        <div class="card">
          <div class="quote">"My days feel steadier. I track three small practices and they pile into calm."</div>
          <div class="meta">– R., 45, designer. Subscription member.</div>
        </div>
        <div class="card">
          <div class="quote">"The checklist was a game-changer. I print and pin it. Small, visible wins."</div>
          <div class="meta">– M., 29, student. Used the 7-day generator.</div>
        </div>
        <div class="card">
          <div class="quote">"The coaching gave me a clear structure without heavy rules. Feels like an ongoing nudge."</div>
          <div class="meta">– S., 52, freelancer. Orchard Intensive alumni.</div>
        </div>
      </div>

      <div style="margin-top:18px;display:flex;gap:12px;flex-wrap:wrap;align-items:center">
        <a class="cta" href="book.html">Schedule a conversation</a>
        <button id="openPractice" style="padding:8px 12px;border-radius:8px;border:0;background:#444;color:#fff">Try a micro-practice</button>
        <a href="pricing.html" style="padding:8px 12px;border-radius:8px;border:1px solid rgba(0,0,0,0.06);text-decoration:none;color:var(--muted)">See offers</a>
      </div>
    </section>

    <section style="margin-top:20px">
      <h3>Real notes, simple outcomes</h3>
      <p class="tiny">Stories center on small habit adoption, clearer days, and reproducible frameworks. No medical claims — only practical, measurable practices.</p>

      <!-- Habit builder compact -->
      <div style="margin-top:12px;background:#fff;padding:12px;border-radius:10px;border:1px solid rgba(16,16,16,0.04);">
        <strong>Create a 7-day checklist</strong>
        <div style="margin-top:8px;display:flex;gap:8px">
          <input id="t1" type="text" placeholder="Habit 1" style="padding:8px;border-radius:8px;border:1px solid #eee" />
          <input id="t2" type="text" placeholder="Habit 2" style="padding:8px;border-radius:8px;border:1px solid #eee" />
          <button id="tg">Make</button>
          <button id="tp">Print</button>
        </div>
        <div id="tgArea" style="margin-top:10px;display:none;background:linear-gradient(180deg,#fbfff8,#fff);padding:8px;border-radius:8px">
          <div id="tgGrid" style="display:grid;grid-template-columns:repeat(8,1fr);gap:6px"></div>
        </div>
      </div>

    </section>

    <footer style="margin-top:26px;color:var(--muted);font-size:13px">
      Reach via <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or <a href="tel:{{PHONE}}">{{PHONE}}</a>
    </footer>
  </div>

  <div id="modal" class="modal" role="dialog" aria-modal="true">
    <div class="modal-card">
      <h4 id="mTitle">Micro Practice</h4>
      <div id="mBody">
        <div style="margin-top:6px;color:#555">Choose a short guided exercise to reset and return to your day steadier.</div>
        <div style="margin-top:10px;display:flex;gap:8px;align-items:center">
          <select id="mSel" style="padding:8px;border-radius:8px">
            <option value="breath">Breathing — 2 min</option>
            <option value="journal">Journaling prompt — 5 min</option>
            <option value="intention">Intention setting — 3 min</option>
          </select>
          <button id="mStart">Start</button>
        </div>
        <div id="mText" style="margin-top:10px;color:var(--muted)">Press Start to begin a guided timer and prompt.</div>
        <div class="controls"><button id="mClose">Close</button></div>
      </div>
    </div>
  </div>

  <script>
    // Testimonials: habit generator
    function id(i){return document.getElementById(i)}
    id('tg').addEventListener('click',()=>{
      const a=id('t1').value.trim();
      const b=id('t2').value.trim();
      const arr=[a,b].filter(Boolean);
      const grid=id('tgGrid');grid.innerHTML='';
      if(arr.length===0){grid.innerHTML='<div style="grid-column:1/-1;padding:8px">Add a habit to build a checklist</div>'}
      else{
        grid.innerHTML='';
        grid.innerHTML+='<div style="font-weight:700;">Day</div>';
        ['M','T','W','Th','F','Sa','Su'].forEach(d=>grid.innerHTML+='<div style="font-weight:700">'+d+'</div>');
        arr.forEach(h=>{grid.innerHTML+='<div style="padding:8px;font-weight:600">'+h+'</div>';for(let i=0;i<7;i++)grid.innerHTML+='<div style="display:flex;justify-content:center;align-items:center"><input type="checkbox"></div>';});
        id('tgArea').style.display='block';
      }
    });
    id('tp').addEventListener('click',()=>window.print());

    // Guided modal logic (simple reuse)
    const modal = id('modal');
    const openMind = id('openPractice');
    const mClose = id('mClose');
    const mStart = id('mStart');
    const mSel = id('mSel');
    const mText = id('mText');
    openMind.addEventListener('click',()=>{modal.classList.add('open');});
    mClose.addEventListener('click',()=>{modal.classList.remove('open');});
    mStart.addEventListener('click',()=>{
      const sel = mSel.value;
      const seconds = sel==='breath'?120: sel==='journal'?300:180;
      mText.textContent = (sel==='breath')? 'Slow inhales and longer exhales. Breathe gently.' : (sel==='journal')? 'Write freely for the time. Prompt: What matters most now?' : 'Select an intention you can remember for the next hour.';
      let start=Date.now();
      mStart.disabled=true;
      const iv = setInterval(()=>{
        const rem = Math.max(0, seconds - Math.floor((Date.now()-start)/1000));
        mText.textContent = mText.textContent.split('\n')[0] + ' (' + rem + 's left)';
        if(rem<=0){clearInterval(iv);mStart.disabled=false;mText.textContent='Done — close when ready.'}
      },500);
    });
    modal.addEventListener('click',e=>{if(e.target===modal)modal.classList.remove('open');});
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Book a Conversation</title>
  <meta name="description" content="Book a session or join a program. Hybrid options available.">
  <style>
    :root{--bg:#fffefc;--ink:#0f1720;--muted:#5d6a6a;--accent:#ff7a59}
    body{margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;background:var(--bg);color:var(--ink)}
    .container{max-width:980px;margin:20px auto;padding:18px}
    header{display:flex;justify-content:space-between;align-items:center}
    nav a{margin-left:12px;text-decoration:none;color:var(--muted);font-weight:600}
    h1{margin:10px 0}
    .form{display:grid;grid-template-columns:1fr 360px;gap:18px}
    .panel{background:white;padding:16px;border-radius:12px;border:1px solid rgba(0,0,0,0.04)}
    label{display:block;font-size:13px;margin-top:8px;color:var(--muted)}
    input,textarea,select{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(0,0,0,0.06);margin-top:6px}
    button{background:var(--accent);color:white;padding:10px 12px;border-radius:10px;border:0}
    .note{font-size:13px;color:var(--muted);margin-top:8px}
    .hb{margin-top:12px}
    .printable{margin-top:10px;padding:10px;border-radius:8px;background:linear-gradient(180deg,#fff,#fffef7)}
    /* simple responsive */
    @media(max-width:880px){.form{grid-template-columns:1fr}}
    .tiny{font-size:13px;color:var(--muted)}
  </style>
</head>
<body>
  <div class="container">
    <header>
      <div style="display:flex;gap:12px;align-items:center">
        <div style="width:44px;height:44px;border-radius:8px;background:linear-gradient(135deg,#ff7a59,#6fc3a6);display:grid;place-items:center;color:white;font-weight:700">W</div>
        <div>
          <div style="font-weight:700">{{BUSINESS_NAME}}</div>
          <div class="tiny">Book time that pairs talk with daily tools.</div>
        </div>
      </div>
      <nav>
        <a href="index.html">Home</a>
        <a href="programs.html">Paths</a>
        <a href="pricing.html">Offers</a>
        <a href="testimonials.html">Voices</a>
        <a href="contact.html">Connect</a>
      </nav>
    </header>

    <main style="margin-top:18px">
      <h1>Schedule a session or join a path</h1>
      <p class="note">Select a time, share what you want to shift, and choose a format: single consult, ongoing subscription, or structured program. Offers blend coaching moments with daily habit frames.</p>

      <div class="form">
        <div class="panel">
          <form id="bookForm">
            <label>Full name</label>
            <input id="name" required placeholder="Your name" />
            <label>Email</label>
            <input id="email" required placeholder="you@domain.com" />
            <label>Phone (optional)</label>
            <input id="phone" placeholder="{{PHONE}}" />
            <label>Format</label>
            <select id="format">
              <option value="single">Single consult (Pulse)</option>
              <option value="sub">Monthly guidance (Compass)</option>
              <option value="intensive">8-week path (Orchard)</option>
            </select>
            <label>What would you like to focus on?</label>
            <textarea id="notes" rows="4" placeholder="Outcomes, current rhythms, what matters..."></textarea>
            <div style="display:flex;gap:8px;align-items:center;margin-top:12px">
              <button type="button" id="submitBtn">Request booking</button>
              <button type="button" id="openPractice">Try a mini-practice</button>
            </div>
            <div class="note">Expect a reply with next steps and any pre-session habits to try.</div>
          </form>
        </div>

        <aside class="panel">
          <strong>Build a 7-day starter</strong>
          <div class="hb">
            <input id="b1" placeholder="Habit A (e.g., 3 mindful breaths)" />
            <input id="b2" placeholder="Habit B (movement)" style="margin-top:8px" />
            <input id="b3" placeholder="Habit C (evening note)" style="margin-top:8px" />
            <div style="display:flex;gap:8px;margin-top:10px">
              <button id="bMake">Make checklist</button>
              <button id="bPrint">Print</button>
            </div>
          </div>

          <div id="bArea" class="printable" style="display:none">
            <div style="display:flex;justify-content:space-between;align-items:center"><strong>Starter checklist</strong><span class="tiny">Pin it up.</span></div>
            <div id="bGrid" style="margin-top:8px;display:grid;grid-template-columns:repeat(8,1fr);gap:6px"></div>
          </div>

          <div style="margin-top:12px;color:var(--muted)">By booking you agree to practical coaching focused on habits and daily frameworks. No medical or therapeutic claims are made.</div>
        </aside>
      </div>

    </main>

    <footer style="margin-top:18px;color:var(--muted)">Questions? Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call <a href="tel:{{PHONE}}">{{PHONE}}</a></footer>
  </div>

  <!-- Modal guided exercise (reusable) -->
  <div id="modal" class="modal" style="position:fixed;inset:0;display:none;align-items:center;justify-content:center;background:rgba(8,8,8,0.36)">
    <div style="background:#fff;padding:16px;border-radius:12px;width:520px;max-width:92%">
      <h3 id="mt">Quick Practice</h3>
      <div style="margin-top:8px;display:flex;gap:8px;align-items:center">
        <select id="sel" style="padding:8px;border-radius:8px">
          <option value="breath">Breathing (2 min)</option>
          <option value="journal">Journaling (5 min)</option>
          <option value="intention">Intention (3 min)</option>
        </select>
        <button id="mStart">Start</button>
        <button id="mClose">Close</button>
      </div>
      <div id="mInfo" style="margin-top:10px;color:var(--muted)">Choose and press Start. A small timer will guide you.</div>
    </div>
  </div>

  <script>
    // Booking form (local only)
    const submitBtn = document.getElementById('submitBtn');
    submitBtn.addEventListener('click',()=>{
      const name=document.getElementById('name').value.trim();
      const email=document.getElementById('email').value.trim();
      if(!name||!email){alert('Please add name and email.');return}
      // Simulate submit
      submitBtn.textContent='Requested';submitBtn.disabled=true;setTimeout(()=>{alert('Thanks — we will reach out soon.');},200);
    });

    // Habit builder in booking
    function mkGrid(parentId,b1,b2,b3){
      const grid=document.getElementById(parentId);
      grid.innerHTML='';
      const labels=['','M','T','W','Th','F','Sa','Su'];
      labels.forEach(l=>{const d=document.createElement('div');d.style.fontWeight='600';d.style.padding='6px';d.style.borderRadius='6px';d.style.border='1px solid rgba(0,0,0,0.04)';d.textContent=l||'Day';grid.appendChild(d);});
      [b1,b2,b3].filter(Boolean).forEach(h=>{const t=document.createElement('div');t.style.padding='8px';t.style.fontWeight='600';t.textContent=h;grid.appendChild(t);for(let i=0;i<7;i++){const cell=document.createElement('div');cell.style.display='flex';cell.style.justifyContent='center';cell.style.alignItems='center';cell.innerHTML='<input type="checkbox">';grid.appendChild(cell);}});
    }
    document.getElementById('bMake').addEventListener('click',()=>{
      const b1=document.getElementById('b1').value.trim();
      const b2=document.getElementById('b2').value.trim();
      const b3=document.getElementById('b3').value.trim();
      if(!b1&&!b2&&!b3){alert('Add at least one habit');return}
      mkGrid('bGrid',b1,b2,b3);
      document.getElementById('bArea').style.display='block';
    });
    document.getElementById('bPrint').addEventListener('click',()=>window.print());

    // Modal practice
    const modal=document.getElementById('modal');
    const modalOpens=document.querySelectorAll('#openPractice');
    modalOpens.forEach(b=>b.addEventListener('click',()=>modal.style.display='flex'));
    document.getElementById('mClose').addEventListener('click',()=>modal.style.display='none');
    document.getElementById('mStart').addEventListener('click',()=>{
      const sel=document.getElementById('sel').value;
      const seconds = sel==='breath'?120: sel==='journal'?300:180;
      const info=document.getElementById('mInfo');
      info.textContent = (sel==='breath')? 'Breathe evenly. Inhale 4, pause 1, exhale 5.' : (sel==='journal')? 'Write without editing. Prompt: What feels true today?' : 'Pick a single action you will return to this hour.';
      let start=Date.now();
      document.getElementById('mStart').disabled=true;
      const iv=setInterval(()=>{
        const rem=Math.max(0,seconds-Math.floor((Date.now()-start)/1000));
        info.textContent = info.textContent.split('(')[0] + ' ('+rem+'s)';
        if(rem<=0){clearInterval(iv);document.getElementById('mStart').disabled=false;info.textContent='Done — you can close.'}
      },400);
    });

  </script>
</body>
</html>"} 
